-- Structural definitions from owner-supplied schema; business defaults not modeled.
CREATE TABLE appointments ("id" serial NOT NULL PRIMARY KEY,"tenant_id" integer,"client_id" integer,"employee_id" integer,"start_time" timestamp with time zone NOT NULL,"status" text,"booked_by" text,"notes" text,"created_at" timestamp with time zone,"is_tentative" boolean,"tentative_reason" text,"num_people" integer,"num_bags_checked" integer,"num_bags_carry_on" integer,"outgoing_flight_info" text,"returning_flight_info" text,"driver_notes" text,"vehicle_id" integer,"booker_name" text,"destination" text,"return_date" timestamp with time zone,"square_payment_id" text,"square_checkout_id" text,"payment_status" text,"payment_amount" numeric,"payment_date" timestamp with time zone,"booking_number" text,"requested_driver_name" text,"payment_method" text,"departure_location" text,"pickup_address" text,"dropoff_address" text,"distance_miles" numeric,"pickup_street" text,"pickup_city" text,"pickup_state" text,"pickup_zip" text,"dropoff_street" text,"dropoff_city" text,"dropoff_state" text,"dropoff_zip" text,"original_amount" numeric,"thankyou_sent_at" timestamp with time zone,"driver_accepted" text,"driver_declined_reason" text,"driver_response_at" timestamp with time zone,"driver_confirmation_token" text,"passenger_confirmed" text,"passenger_cancelled_reason" text,"passenger_response_at" timestamp with time zone,"passenger_confirmation_token" text,"num_car_seats" integer,"num_golf_bags" integer,"customs_clearance_location" text,"is_international_flight" boolean,"driver_paid" boolean,"driver_paid_at" timestamp with time zone,"driver_paid_by" text,"vehicle_category" text,"driver_commission" numeric,"services_total" numeric,"balance_due" numeric,"payments_total" numeric,"tips_total" numeric,"is_tour" boolean,"tour_end_time" timestamp with time zone,"tour_participant_type" text,"tour_flat_fee" numeric,"tour_payment_split" text,"distance_method" text,"last_modified_by" text,"display_long_date" text,"display_short_date" text,"display_time" text,"display_full_datetime" text,"display_sms_datetime" text,"display_office_datetime" text,"display_gcal_date" text,"display_return_date" text,"display_tour_end_time" text,"display_payment_method" text,"display_pickup_address" text,"display_dropoff_address" text,"needs_receipt" boolean,"gift_certificate" text,"square_invoice_card_type" text,"wedding_id" integer,"trip_commission_rate" numeric,"payroll_processed" boolean,"cc_fee_amount" numeric,"is_third_party" boolean,"partner_company_id" integer,"partner_company_name" text,"partner_logo_url" text,"partner_billing_email" text,"partner_billing_phone" text,"partner_billing_address" text,"invoice_brand_name" text,"receipt_footer_note" text,"passenger_payer_name" text,"passenger_payer_email" text,"passenger_payer_phone" text,"bill_to_passenger" boolean,"internal_operator" text,"booked_by_dispatcher" text,"special_items" text,"equipment" text);
CREATE TABLE appointment_services ("id" serial NOT NULL PRIMARY KEY,"appointment_id" integer,"service_id" integer,"service_price" numeric NOT NULL,"duration_minutes" integer NOT NULL,"quantity" integer,"stop_description" text);
CREATE TABLE settings ("id" serial NOT NULL PRIMARY KEY,"tenant_id" integer,"key" text NOT NULL,"value" text);
